import React, { useState } from "react";
import "./App.css";
import botIcon from "./bot-icon.png";

const App = () => {
  const [activeSection, setActiveSection] = useState("chat"); // Default: Chat section

  return (
    <div className="app-container">
      {/* Sidebar */}
      <nav className="sidebar">
        <h2>AI Tutor</h2>
        <ul>
          <li onClick={() => setActiveSection("chat")}>💬 Chat</li>
          <li onClick={() => setActiveSection("progress")}>📊 Progress</li>
          <li onClick={() => setActiveSection("settings")}>⚙️ Settings</li>
        </ul>
      </nav>

      {/* Main Content */}
      <div className="content">
        {activeSection === "chat" && (
          <div className="chat-box">
            <div className="message bot">
              <img src={botIcon} alt="Bot" className="bot-icon" />
              <p>Welcome! How can I assist you today?</p>
            </div>
            <input type="text" placeholder="Type a message..." className="chat-input" />
          </div>
        )}

        {activeSection === "progress" && (
          <div className="progress-section">
            <h2>📊 Your Learning Progress</h2>
            <p>Track your AI learning progress here!</p>
          </div>
        )}

        {activeSection === "settings" && (
          <div className="settings-section">
            <h2>⚙️ Settings</h2>
            <p>Customize your experience.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default App;
